-- 164: Original BrillaPrep WASSCE BrillaPrep transitional Building Construction beta content blueprint questions, part 1.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_164_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_164_guard;
INSERT INTO _migration_164_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_001' AND NOT (q.topic_id IS 'topic_was_building_b003_1' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the first control required before workers enter an unsupported excavation?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Provide an appropriate protective system and safe access","B. Stack excavated soil at the trench edge","C. Rely on the soil standing for the duration of the work","D. Send one worker ahead to test the sides by hand"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Excavation sides can collapse without warning, so shoring, shielding or safe battering must be selected for the ground conditions and accompanied by secure access. Therefore the correct answer is A: Provide an appropriate protective system and safe access.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_001' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_164_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_002' AND NOT (q.topic_id IS 'topic_was_building_b003_1' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which instrument is best suited to transferring the same horizontal level around a building site?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A plumb bob and line","B. An automatic or dumpy level with a staff","C. A builder’s square","D. A steel float"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A level establishes a horizontal line of sight and staff readings transfer or compare reduced levels accurately between separated points on the site. Therefore the correct answer is B: An automatic or dumpy level with a staff.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_002' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_164_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_003' AND NOT (q.topic_id IS 'topic_was_building_b003_1' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why are profile boards placed beyond the excavation lines during setting out?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. They permanently support the foundation concrete","B. They mark only the location of stored materials","C. They preserve building lines and levels while excavation proceeds","D. They replace all diagonal checks of the layout"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Profiles carry string lines and level marks outside the disturbed ground, allowing centre lines and wall faces to be re-established after excavation. Therefore the correct answer is C: They preserve building lines and levels while excavation proceeds.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_1' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_003' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_164_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_004' AND NOT (q.topic_id IS 'topic_was_building_b003_1' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How is a rectangular building corner checked accurately before excavation?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Measure only one long side twice","B. Check that every profile is the same colour","C. Use a plumb bob to compare ground areas","D. Compare diagonals after setting the required side lengths"]' AND q.correct_answer IS 'D' AND q.explanation IS 'For a true rectangle with fixed side lengths, equal diagonals provide a direct check that the corners are square rather than skewed. Therefore the correct answer is D: Compare diagonals after setting the required side lengths.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_1' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_004' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_164_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_building_b003_005' AND NOT (q.topic_id IS 'topic_was_building_b003_1' AND q.subject_id IS 'subj_wassce_building' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the safest way to carry long reinforcement bars through an active site?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Use coordinated handlers and maintain clear awareness of both ends","B. Carry them vertically beneath overhead power lines","C. Drag them across access routes without warning","D. Balance several bars on one shoulder while running"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Long bars create striking, trip and electrical hazards; coordinated handling, clear routes and control of both ends reduce those risks. Therefore the correct answer is A: Use coordinated handlers and maintain clear awareness of both ends.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_building_b003_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_building_b003_005' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Building Construction practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
